def resolve(path, cwd, links):
    # Start with absolute path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split path into components
    components = remaining.split('/')

    # Track symlinks followed
    links_followed = 0

    i = 0
    while i < len(components):
        component = components[i]
        i += 1

        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append the component
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if this is a symlink
        if candidate in links:
            links_followed += 1
            if links_followed > 8:
                return None

            target = links[candidate]

            # Resolve remaining components after this symlink
            remaining_components = components[i:]

            # Process the target
            if target.startswith('/'):
                current = '/'
                target_path = target[1:]
            else:
                # Target is relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_path = target

            # Prepend remaining components to target components
            target_components = target_path.split('/') if target_path else []
            components = target_components + remaining_components
            i = 0
        else:
            # Not a symlink, just move to this path
            current = candidate

    # Return result with no trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current

